map_t shirohebi_map;

/* Fill the exported 20-by-18 map descriptor with its tile, collision and event tables. */
void shirohebi_build_map()
{
    shirohebi_map.width = 20;
    shirohebi_map.height = 18;
    shirohebi_map.bank_tiles = 0;
    shirohebi_map.tiles = shirohebi_map_tiles;
    shirohebi_map.collision_bits = shirohebi_collision_bits;
    shirohebi_map.events = shirohebi_events;
}

/* Copy the two exported 2bpp background tiles into VRAM at 0x8000; the caller must make VRAM
   accessible. */
void shirohebi_upload_tiles()
{
    __vram_copy(0x8000, shirohebi_tile_data, 32);
}

/* Upload CGB attributes one visible row at a time, converting the packed 20-column source to
   the 32-column hardware stride. */
void shirohebi_apply_attrs()
{
    u8 y = 0;
    u8 rows = 18;
    u8 cols = 20;
    if (rows > 18) rows = 18;
    if (cols > 20) cols = 20;
    while (y < rows) {
        __settileattr_bulk_fast((u16)(0x9800 + ((u16)y * 32)), shirohebi_map_attrs + ((u16)y * 20), cols);
        y++;
    }
}

/* Provide the asset export's general loader: tiles, map descriptor, map contents, then CGB
   attributes. The game also supports partial cell updates. */
void shirohebi_load()
{
    shirohebi_upload_tiles();
    shirohebi_build_map();
    map_load(0, &shirohebi_map);
    shirohebi_apply_attrs();
}
